const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define southern Spain region (Andalusia)
  const southernSpain = ee.Geometry.Polygon([
    [[-6, 36], [-1, 36], [-1, 38], [-6, 38], [-6, 36]]
  ]);

  // 2. Load ERA5 temperature data for April 2023
  const era5 = ee.ImageCollection('COPERNICUS/ERA5/MONTHLY')
    .filter(ee.Filter.date('2023-04-01', '2023-05-01'))
    .select('mean_2m_air_temperature');

  const collectionSize = era5.size().getInfo();
  console.log(`ERA5 Images in April 2023: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No ERA5 data found for April 2023.");
    console.log("C1");
    return;
  }

  // 3. Calculate mean temperature over southern Spain
  const meanTemp = era5.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southernSpain,
    scale: 11132,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo();

  if (meanTemp === null || isNaN(meanTemp)) {
    console.log("Temperature calculation returned null or NaN.");
    console.log("C3");
    return;
  }

  // 4. Convert from Kelvin to Celsius and then to Fahrenheit
  const tempCelsius = meanTemp - 273.15;
  const tempFahrenheit = (tempCelsius * 9/5) + 32;

  // 5. Also get maximum temperature for context
  const maxTemp = era5.max().reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: southernSpain,
    scale: 11132,
    maxPixels: 1e9
  }).get('mean_2m_air_temperature').getInfo();

  const maxTempFahrenheit = (maxTemp - 273.15) * 9/5 + 32;

  // 6. Validation and answer
  console.log(`April 2023 Southern Spain - Mean Temp: ${tempFahrenheit.toFixed(1)}°F (${tempCelsius.toFixed(1)}°C)`);
  console.log(`April 2023 Southern Spain - Max Temp: ${maxTempFahrenheit.toFixed(1)}°F`);
  console.log(`Pixel Count: ${collectionSize}`);

  // Check if temperatures exceed 90°F (32.2°C)
  const threshold90F = 32.2; // Celsius equivalent

  if (tempFahrenheit > 90 || maxTempFahrenheit > 90) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
